function useManualMineDeposit() {
  const { actor } = useActor();
  const queryClient2 = useQueryClient();
  return useMutation({
    mutationFn: async (depositId) => {
      if (!actor) return null;
      try {
        return await actor.mineDeposit(depositId);
      } catch {
        return null;
      }
    },
    onSuccess: () => {
      void queryClient2.invalidateQueries({ queryKey: ["substrateMine"] });
      void queryClient2.invalidateQueries({ queryKey: ["miningState"] });
    }
  });
}
